mapper.sql:
FROM crm_customer c LEFT JOIN sys_user o ON o.tenant_id=c.tenant_id AND o.id=c.owner_staff_id
WHERE c.tenant_id=#{q.tenantId} AND c.deleted=0

AND c.id=#{q.filter.customerId}
AND c.customer_status=#{q.filter.status}
AND c.city_code=#{q.filter.cityCode}
AND c.source_code=#{q.filter.sourceCode}
AND c.channel_code=#{q.filter.channelCode}
AND c.created_at>=#{q.filter.from}
AND c.created_at<=#{q.filter.to}

FROM crm_order o INNER JOIN crm_customer c ON c.tenant_id=o.tenant_id AND c.id=o.customer_id AND c.deleted=0
WHERE o.tenant_id=#{q.tenantId}

AND o.customer_id=#{q.filter.customerId}
AND o.status=#{q.filter.status}
AND o.source_system=#{q.filter.sourceSystem}
AND o.ordered_at>=#{q.filter.from}
AND o.ordered_at<=#{q.filter.to}

FROM crm_redemption r LEFT JOIN crm_customer c ON c.tenant_id=r.tenant_id AND c.id=r.customer_id
WHERE r.tenant_id=#{q.tenantId}

AND r.customer_id=#{q.filter.customerId}
AND r.status=#{q.filter.status}
AND r.service_at>=#{q.filter.from}
AND r.service_at<=#{q.filter.to}

FROM crm_followup f INNER JOIN crm_customer c ON c.tenant_id=f.tenant_id AND c.id=f.customer_id AND c.deleted=0
LEFT JOIN sys_user o ON o.tenant_id=f.tenant_id AND o.id=f.owner_staff_id
WHERE f.tenant_id=#{q.tenantId} AND f.deleted=0

AND f.customer_id=#{q.filter.customerId}
AND f.channel_code=#{q.filter.channelCode}
AND f.contact_at>=#{q.filter.from}
AND f.contact_at<=#{q.filter.to}
